  ('dca58c72-0822-496c-bfca-d146e578e03b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '41600890-6891-445f-81e2-fb36c9739348', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$रंग थे। मैंने कई अलग-अलग रंगों की रेत को हाथ में लेकर देखा और मसलकर नीचे गिर जाने दियया। जिन रंगों को हाथों से नहीं छू सका, उन््हें पैरों से मसल दियया। मन था कि किसी तरह हर रंग की थोड़ी-थोड़ी रेत अपने पास रख लूँ। पर उसका कोई उपायय नहीं था। यह सोचकर कि फिर किसी दिन आकर उस रेत को बटोरूँगा, मैं उदास मन से वहाँ से आगे चल दियया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-41-324Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8fc02773-06cf-45bc-980c-cf9272d61939', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '41600890-6891-445f-81e2-fb36c9739348', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$समुद्र में पानी बढ़ रहा था। तट की चौड़ाई धीरे-धीरे कम होती जा रही थी। एक लहर मेरे पैरों को भिगो गई, तो सहसा मुझे खतरे का एहसास हुआ। मैं जल्दी-जल्दी चलने लगा। तट का सिर््फ तीन-तीन चार-चार फुट हिस्सा पानी से बाहर था। लग रहा था कि जल्दी ही पानी उसे भी अपने अंदर समा लेगा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-41-324Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b1802ea7-b06c-48f3-b1bd-9f945eb30248', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '41600890-6891-445f-81e2-fb36c9739348', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक बार सोचा कि खड़ी रेत से होकर फिर ऊपर चला जाऊँ। पर वह स््ययाह पड़ती रेत इस तरह दीवार की तरह उठठी थी कि उस रास्ते ऊपर जाने की कोशिश करना ही बेकार था। मेरे मन में खतरा बढ़ गयया। मैं दौड़ने लगा। दो-एक और लहरें पैरों के नीचे तक आकर लौट गइ«। मैंने जूता उतारकर हाथ में ले लियया। एक ऊँची लहर से बचकर इस तरह दौड़ा जैसे सचमुच वह मुझे अपनी लपेट में लेने आ रही हो।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-41-324Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('29eb677b-5126-4b3c-96f7-3d6c312f8808', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '41600890-6891-445f-81e2-fb36c9739348', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सामने एक ऊँची चट्टान थी। वक्‍त पर अपने को संभालने की कोशिश की, फिर भी उससे टकरा गयया। बाँहों पर हल्की खरोंच आ गई, पर ज््‍ययायादा चोट नहीं लगी। चट्टान पानी के अंदर तक चली गई थी— उसे बचाकर आगे जाने के लिए पानी में उतरना आवश््यक था। पर उस समयय पानी की तरफ पाँव बढ़ाने का मेरा साहस नहीं हुआ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-41-324Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e0f7c7d5-7a5e-4012-bbfc-1e1b38798d5e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '41600890-6891-445f-81e2-fb36c9739348', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं चट्टान की नोकों पर पैर रखता किसी तरह उसके ऊपर पहुँच गयया। सोचा नीचे खड़े रहने की अपेक्षा वह अधिक सुरक्षित होगा। पर ऊपर पहुँचकर लगा जैसे मेरे साथ एक मजाक कियया गयया हो। चट्टान के उस तरफ तट का खुला फैलाव था— लगभग सौ फुट का। कितने ही लोग वहाँ टहल रहे थे। ऊपर सड़क पर जाने के लिए वहाँ से रास्ता भी बना था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-41-324Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
