  ('6fa5b2f9-b0a5-44aa-b94d-99103b75ff4f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '41600890-6891-445f-81e2-fb36c9739348', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सूर्य-दर्शन। मेरा साथी अब मुहल्ले-मुहल्ले के हिसाब से मुझे बेकारी के आँकड़े बता रहा था। बहुत-से कडल-काक हमारे आस-पास तैर रहे थे— वहाँ की बेकारी की समस््या और सूर्योदयय की विशेषता, इन दोनों से बे-लाग।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-41-324Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('f3e54991-2a0d-47f5-8c4f-fbe6726ef304', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '41600890-6891-445f-81e2-fb36c9739348', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कन््याकुमारी के मंदिर में पूजा की घंटिययाँ बज रही थीं। भक्‍तों की एक मंडली अंदर जाने से पहले मंदिर की दीवार के पास रुककर उसे प्रणाम कर रही थी। सरकारी मेहमान गेस्ट-हाउस की तरफ लौट रहे थे। हमारी नाव और किनारे के बीच हल्की धूप में कई एक नावों के पाल और कडल-काकों के पंख एक-से चमक रहे थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-41-324Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('52537178-9ec9-4fd8-b942-6582646a0d42', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '41600890-6891-445f-81e2-fb36c9739348', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं अब भी आँखों से बीच की दूरी नाप रहा था और मन में बसों का टाइम-टेबल दोहरा रहा था। तीसरी बस नौ चालीस पर, चौथी...।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-41-324Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
